{
	int r;

	if (refcount_inc_not_zero(&cell->ref)) {
		r = refcount_read(&cell->ref);
		trace_afs_cell(cell->debug_id, r, atomic_read(&cell->active), reason);
		return cell;
	}
	return NULL;
}

